"use client";
import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { ArrowUpRight, Clock, Tag, BookOpen, Search, User } from 'lucide-react';
import { db } from '@/firebase';
import { collection, getDocs, query, orderBy, where } from 'firebase/firestore';

export default function BlogPage() {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    // Basic SEO meta tags injection
    document.title = 'Web Dev Blog | Suleman Zaheer';
    let metaDesc = document.querySelector('meta[name="description"]');
    if (!metaDesc) {
      metaDesc = document.createElement('meta');
      metaDesc.name = 'description';
      document.head.appendChild(metaDesc);
    }
    metaDesc.content = 'Expert articles on MERN Stack, Next.js, React, and web engineering by Suleman Zaheer.';

    const fetchBlogs = async () => {
      try {
        const q = query(
          collection(db, 'blogs'), 
          where('published', '==', true),
          orderBy('publishedAt', 'desc')
        );
        const snapshot = await getDocs(q);
        setPosts(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
      } catch (error) {
        console.error("Error fetching blogs:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchBlogs();
  }, []);

  const generateSchema = () => {
    return {
      '@context': 'https://schema.org',
      '@type': 'Blog',
      name: 'Suleman Zaheer – Web Development Blog',
      description: 'Expert articles on MERN Stack, Next.js, React, and web engineering by Suleman Zaheer, Full Stack Developer from Lahore, Pakistan.',
      url: 'https://suleman-zaheer.web.app/blog',
      author: {
        '@type': 'Person',
        name: 'Suleman Zaheer',
        url: 'https://suleman-zaheer.web.app',
      },
      blogPost: posts.map(post => ({
        '@type': 'BlogPosting',
        headline: post.title,
        description: post.excerpt,
        datePublished: post.publishedAt?.toDate ? post.publishedAt.toDate().toISOString() : new Date().toISOString(),
        author: {
          '@type': 'Person',
          name: 'Suleman Zaheer',
        },
        url: `https://suleman-zaheer.web.app/blog/${post.slug}`,
      }))
    };
  };

  const filteredPosts = posts.filter(post => 
    post.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    post.excerpt.toLowerCase().includes(searchTerm.toLowerCase()) ||
    post.tags?.some(tag => tag.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  return (
    <main className="min-h-screen bg-neutral-950 text-white font-sans selection:bg-primary/30">
      {!loading && posts.length > 0 && (
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(generateSchema()) }}
        />
      )}

      <div className="pt-32 pb-24 relative overflow-hidden">
        {/* Background glow */}
        <div className="absolute top-0 left-1/2 w-[600px] h-[400px] -translate-x-1/2 bg-primary/5 blur-[150px] rounded-full pointer-events-none" />

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
          {/* Header */}
          <div className="text-center mb-16">
            <div className="inline-flex items-center gap-3 px-5 py-2 rounded-full bg-primary/10 border border-primary/20 text-primary text-sm font-bold mb-6">
              <BookOpen size={16} />
              Developer Insights
            </div>
            <h1 className="text-4xl sm:text-5xl md:text-7xl font-display font-black leading-tight tracking-tighter text-white mb-6">
              Web Dev <span className="text-gray-600">Blog</span>
              <br />
              <span className="text-primary italic font-medium text-4xl sm:text-5xl">
                by Suleman Zaheer
              </span>
            </h1>
            <p className="text-gray-400 max-w-2xl mx-auto text-lg leading-relaxed">
              In-depth articles on MERN Stack, Next.js, React, Node.js, freelancing, and modern software engineering — written from real project experience.
            </p>
          </div>

          {/* Search Bar */}
          <div className="max-w-2xl mx-auto mb-16 relative">
            <div className="absolute inset-y-0 left-4 flex items-center pointer-events-none">
              <Search className="h-5 w-5 text-gray-500" />
            </div>
            <input
              type="text"
              className="w-full bg-white/5 border border-white/10 text-white rounded-2xl pl-12 pr-4 py-4 focus:outline-none focus:border-primary/50 transition-colors"
              placeholder="Search articles by title, excerpt, or tags..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          {/* Posts Grid */}
          {loading ? (
            <div className="flex justify-center items-center py-20">
              <div className="w-12 h-12 border-4 border-primary/20 border-t-primary rounded-full animate-spin" />
            </div>
          ) : filteredPosts.length === 0 ? (
            <div className="text-center py-20 border border-dashed border-white/10 rounded-3xl bg-white/[0.02]">
              <BookOpen className="w-12 h-12 text-gray-600 mx-auto mb-4" />
              <h2 className="text-2xl font-bold text-gray-300 mb-2">No articles found</h2>
              <p className="text-gray-500">Try adjusting your search criteria.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {filteredPosts.map((post, index) => (
                <Link
                  href={`/blog/${post.slug}`}
                  key={post.id}
                  className={`group relative p-8 rounded-[2rem] bg-white/[0.02] border border-white/5 hover:border-primary/30 transition-all duration-300 flex flex-col gap-6 ${index === 0 && !searchTerm ? 'lg:col-span-2' : ''}`}
                >
                  <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-primary/0 to-transparent group-hover:via-primary/50 transition-all duration-500 rounded-t-[2rem]" />

                  {/* Meta */}
                  <div className="flex flex-wrap items-center gap-4 text-xs text-gray-500 font-medium">
                    <span className="flex items-center gap-1.5 bg-white/5 px-3 py-1 rounded-full">
                      <Clock size={12} className="text-primary" />
                      {post.readTime || '5 min read'}
                    </span>
                    <span className="flex items-center gap-1.5 bg-white/5 px-3 py-1 rounded-full">
                      <User size={12} className="text-primary" />
                      Suleman Zaheer
                    </span>
                    <span className="text-gray-600 ml-auto">
                      {post.publishedAt?.toDate ? new Date(post.publishedAt.toDate()).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' }) : 'Recently'}
                    </span>
                  </div>

                  {/* Title & Excerpt */}
                  <div>
                    <h2 className={`font-bold text-white mb-3 group-hover:text-primary transition-colors leading-snug ${index === 0 && !searchTerm ? 'text-2xl sm:text-4xl' : 'text-xl sm:text-2xl'}`}>
                      {post.title}
                    </h2>
                    <p className={`text-gray-400 leading-relaxed ${index === 0 && !searchTerm ? 'text-base sm:text-lg' : 'text-sm sm:text-base'}`}>
                      {post.excerpt}
                    </p>
                  </div>

                  {/* Tags & Read More */}
                  <div className="mt-auto pt-6 border-t border-white/5 flex flex-wrap items-center justify-between gap-4">
                    <div className="flex flex-wrap gap-2">
                      {post.tags?.slice(0, 3).map((tag) => (
                        <span
                          key={tag}
                          className="flex items-center gap-1 px-3 py-1 rounded-full bg-white/5 text-[10px] font-bold text-gray-400 uppercase tracking-wider"
                        >
                          <Tag size={9} />
                          {tag}
                        </span>
                      ))}
                      {post.tags?.length > 3 && (
                        <span className="px-3 py-1 rounded-full bg-white/5 text-[10px] font-bold text-gray-500 uppercase tracking-wider">
                          +{post.tags.length - 3}
                        </span>
                      )}
                    </div>
                    <span className="inline-flex items-center gap-2 text-primary text-sm font-bold group-hover:translate-x-2 transition-transform">
                      Read Article <ArrowUpRight size={16} />
                    </span>
                  </div>
                </Link>
              ))}
            </div>
          )}

          {/* CTA */}
          <div className="mt-20 text-center p-12 rounded-[3rem] bg-white/[0.02] border border-white/5">
            <h3 className="text-3xl font-bold text-white mb-4">Want to Work Together?</h3>
            <p className="text-gray-400 mb-8 max-w-lg mx-auto">
              I'm Suleman Zaheer, a Full Stack Developer from Lahore, Pakistan. If you need a high-performance web application, let's talk.
            </p>
            <div className="flex flex-wrap gap-4 justify-center">
              <a
                href="https://wa.me/923285778715"
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-2 bg-primary text-white px-8 py-4 rounded-2xl font-bold hover:bg-primary/90 transition-all hover:scale-105"
              >
                Hire Me on WhatsApp <ArrowUpRight size={18} />
              </a>
              <Link
                href="/projects"
                className="inline-flex items-center gap-2 bg-white/5 border border-white/10 text-white px-8 py-4 rounded-2xl font-bold hover:bg-white/10 transition-all"
              >
                View My Projects <ArrowUpRight size={18} />
              </Link>
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}
